#include <string>
#include <algorithm>

class Solution {
public:
    std::string convertBase(std::string val, int from_base, int to_base) {
        std::string digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        long long num = 0;
        for (char ch : val) {
            char u = std::toupper(ch);
            num = num * from_base + digits.find(u);
        }
        if (num == 0) return "0";

        std::string res = "";
        while (num > 0) {
            res += digits[num % to_base];
            num /= to_base;
        }
        std::reverse(res.begin(), res.end());
        return res;
    }
};

class Solution {
    public String convertBase(String val, int fromBase, int toBase) {
        String digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        long num = 0;
        for (int i = 0; i < val.length(); i++) {
            char ch = Character.toUpperCase(val.charAt(i));
            num = num * fromBase + digits.indexOf(ch);
        }
        if (num == 0) return "0";

        StringBuilder sb = new StringBuilder();
        while (num > 0) {
            sb.append(digits.charAt((int)(num % toBase)));
            num /= toBase;
        }
        return sb.reverse().toString();
    }
}

