var convertBase = function(val, from_base, to_base) {
    const digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    let num = 0n;
    const fb = BigInt(from_base);
    const tb = BigInt(to_base);

    for (let i = 0; i < val.length; i++) {
        const u = val[i].toUpperCase();
        num = num * fb + BigInt(digits.indexOf(u));
    }
    if (num === 0n) return "0";

    const res = [];
    while (num > 0n) {
        const rem = Number(num % tb);
        res.push(digits[rem]);
        num /= tb;
    }
    return res.reverse().join("");
};
